<template>
  <section class="draw-assistant" :data-stage="stage">
    <div class="assistant-scene">
      <span class="scene-grid" aria-hidden="true"></span><span class="pink-breath" aria-hidden="true"></span><span class="particle-stream" aria-hidden="true"><i></i><i></i><i></i></span><i class="star one" aria-hidden="true">✦</i><i class="star two" aria-hidden="true">✧</i><i class="star three" aria-hidden="true">✦</i><i class="orb" aria-hidden="true"></i><i class="code-glyph" aria-hidden="true">&lt;/&gt;</i>
      <Transition name="character-fade" mode="out-in"><img :key="characterSrc" class="assistant-character" :src="characterSrc" :alt="`原创绘图助手：${currentCopy}`" draggable="false"></Transition>
      <div class="status-bubble" :class="stage" aria-live="polite">
        <img :src="statusIcon" alt="" aria-hidden="true"><span>{{ statusText || currentCopy }}</span>
        <i v-if="isWorking" class="loading-dots" aria-hidden="true"><b></b><b></b><b></b></i><strong v-else-if="stage==='success'" aria-hidden="true">✓</strong><strong v-else-if="stage==='error'" aria-hidden="true">!</strong>
      </div>
    </div>
    <div class="input-shell">
      <span class="sparkle" aria-hidden="true">✦</span><textarea :value="modelValue" :disabled="loading" rows="2" aria-label="绘图需求" placeholder="输入需求，绘图助手帮你生成…" @input="$emit('update:modelValue',$event.target.value)" @keydown="onKeydown"></textarea>
      <button v-if="loading" type="button" class="send stop" aria-label="停止生成" @click="$emit('stop')">■</button><button v-else type="button" class="send" :disabled="!canSend" aria-label="发送绘图需求" @click="$emit('send')"><img src="/draw-assistant/icons/ui/send.svg" alt=""></button>
    </div>
    <div class="mini-progress" aria-label="绘图生成进度">
      <template v-for="(item,index) in steps" :key="item.key"><span :class="stepState(index)"><i>{{ index+1 }}</i><b>{{ item.label }}</b><em v-if="stepState(index).done">✓</em><em v-else-if="stepState(index).error">!</em></span><small v-if="index<steps.length-1" aria-hidden="true"></small></template>
    </div>
    <details class="details"><summary><span>详情与快捷操作</span><img src="/draw-assistant/icons/ui/more.svg" alt=""></summary><div class="detail-actions"><button v-for="item in quickCommands" :key="item" :disabled="loading" @click="$emit('quick',item)">{{ item }}</button></div><div class="messages"><p v-for="(message,index) in messages" :key="index" :class="message.role"><b>{{ message.role==='user'?'我':'助手' }}</b>{{ message.text }}</p></div><footer><button v-if="hasUndo" :disabled="loading" @click="$emit('undo')">撤销上次AI修改</button><button :disabled="loading" @click="$emit('clear')">清空对话</button></footer></details>
  </section>
</template>

<script setup>
import { computed, watch } from 'vue'
const props=defineProps({stage:{type:String,default:'idle'},statusText:{type:String,default:''},modelValue:{type:String,default:''},loading:Boolean,canSend:Boolean,messages:{type:Array,default:()=>[]},quickCommands:{type:Array,default:()=>[]},hasUndo:Boolean})
const emit=defineEmits(['update:modelValue','send','stop','clear','undo','quick'])
const copy={idle:'等待输入',analyzing:'正在理解需求…',generating:'正在生成代码…',assembling:'正在拼装代码…',rendering:'正在渲染图形…',success:'生成完成',error:'生成失败，请重试'},iconNames={idle:'analyze',analyzing:'analyze',generating:'code',assembling:'assemble',rendering:'render',success:'complete',error:'error'},characterNames={idle:'idle',analyzing:'analyzing',generating:'generating',assembling:'assembling',rendering:'rendering',success:'success',error:'error'},steps=[{key:'generating',label:'生成代码'},{key:'assembling',label:'拼装代码'},{key:'rendering',label:'渲染图形'},{key:'success',label:'完成'}],stageIndexes={generating:0,assembling:1,rendering:2,success:3}
let lastProgressIndex=0
watch(()=>props.stage,value=>{if(Number.isInteger(stageIndexes[value]))lastProgressIndex=stageIndexes[value]},{immediate:true})
const currentCopy=computed(()=>copy[props.stage]||copy.idle),characterSrc=computed(()=>`/draw-assistant/seven-states-hd/assistant_${characterNames[props.stage]||'idle'}.png`),statusIcon=computed(()=>`/draw-assistant/icons/status/${iconNames[props.stage]||'analyze'}.svg`),isWorking=computed(()=>['analyzing','generating','assembling','rendering'].includes(props.stage))
function stepState(index){if(props.stage==='idle'||props.stage==='analyzing')return {pending:true,preparing:props.stage==='analyzing'&&index===0};if(props.stage==='error')return {done:index<lastProgressIndex,error:index===lastProgressIndex,pending:index>lastProgressIndex};if(props.stage==='success')return {done:true,final:index===3};const active=stageIndexes[props.stage];return {active:active===index,done:Number.isInteger(active)&&index<active,pending:index>active}}
function onKeydown(event){if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();if(props.canSend&&!props.loading)emit('send')}}
</script>

