.character-fade-enter-active,.character-fade-leave-active{transition:opacity .22s ease}.character-fade-enter-from,.character-fade-leave-to{opacity:0}.assistant-character{animation:assistantFloat 4.2s ease-in-out infinite}.draw-assistant[data-stage="error"] .pink-breath,.draw-assistant[data-stage="error"] .particle-stream,.draw-assistant[data-stage="error"] .star,.draw-assistant[data-stage="error"] .orb{animation-duration:10s;opacity:.22}@keyframes assistantFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}@keyframes pinkBreath{0%,100%{opacity:.52;transform:scale(.96) translate3d(0,0,0)}50%{opacity:.88;transform:scale(1.08) translate3d(4%,2%,0)}}@keyframes particleFlow{0%,100%{opacity:.16;transform:translate3d(-8px,7px,0) scale(.75)}50%{opacity:.52;transform:translate3d(18px,-7px,0) scale(1.05)}}@keyframes gridDrift{to{background-position:14px 0,28px 0,28px 0}}@keyframes starPulse{0%,100%{opacity:.28;transform:scale(.8)}50%{opacity:.82;transform:scale(1.12)}}@keyframes orbFloat{0%,100%{transform:translate3d(0,0,0);opacity:.42}50%{transform:translate3d(-8px,-5px,0);opacity:.75}}@keyframes dot{0%,70%,100%{opacity:.25;transform:translateY(0)}35%{opacity:1;transform:translateY(-2px)}}
